<template>
  <CanvasserFormWrapper title="Canvasser Application">
    <GeneralInfoForm
      variant="create"
      submit-label="Apply"
      :is-saving="isSettingCanvasserApplication"
      :on-submit="onSubmit"
    />
  </CanvasserFormWrapper>
</template>

<script lang="ts" setup>
import { useSetCanvasserApplication } from '~/mutations/account';
import type { CanvasserGeneralInfoForm } from '~/client';

definePageMeta({
  roles: ['canvasser'],
});

useHead({ title: 'Canvasser Application' });

const { setCanvasserApplication, isSettingCanvasserApplication } = useSetCanvasserApplication();

const onSubmit = async (values: CanvasserGeneralInfoForm) => {
  await setCanvasserApplication(values);
};
</script>
