import { postCanvasserGeneralInfo, type CanvasserGeneralInfoForm } from '~/client';

export const useSetCanvasserApplication = defineMutation(() => {
  const refreshAccountAndRedirect = useRefreshAccountAndRedirect();

  const { mutateAsync: setCanvasserApplication, asyncStatus } = useMutation({
    mutation: (applicationForm: CanvasserGeneralInfoForm) =>
      postCanvasserGeneralInfo({
        composable: '$fetch',
        body: {
          ...applicationForm,
        },
      }),
    onSuccess: async () => {
      showToastSuccess('Application submitted successfully');
      await refreshAccountAndRedirect();
    },
    onError: (error) => {
      console.error('Error setting canvasser application:', error);
      showToastError(error);
    },
  });

  return {
    setCanvasserApplication,
    isSettingCanvasserApplication: computed(() => asyncStatus.value === 'loading'),
  };
});
